// SPDX-License-Identifier: CECILL-2.1
// HDBSCAN reference gate against parity/fixtures/hdbscan_v1.json, generated by
// parity/generators/hdbscan_v1.py from scikit-learn 1.9.1 and hdbscan 0.8.44
// (stable MST tie order). Partitions are compared up to label permutation.
#include <cmath>
#include <cstdint>
#include <cstdio>
#include <map>
#include <stdexcept>
#include <string>
#include <vector>

#include "fixture_parser.hpp"
#include "n4m/n4m.h"

#define REQUIRE(x) do { if (!(x)) throw std::runtime_error(std::string(#x) + " @" + std::to_string(__LINE__)); } while (false)

namespace {
using namespace n4m_testing;

struct Output {
    std::vector<int64_t> labels, tree_parent, tree_size, tree_label;
    std::vector<double> membership, outlier, persistence, birth, death, stability;
    int64_t n_clusters = 0, n_nodes = 0;
};

n4m_status_t run(n4m_context_t* ctx, const n4m_matrix_view_t& X, int64_t mcs, int64_t ms,
                 int32_t method, int32_t single, Output& o) {
    const auto n = static_cast<size_t>(X.rows);
    o.labels.assign(n, 0); o.tree_parent.assign(n, 0); o.tree_size.assign(n, 0);
    o.tree_label.assign(n, 0); o.membership.assign(n, 0); o.outlier.assign(n, 0);
    o.persistence.assign(n, 0); o.birth.assign(n, 0); o.death.assign(n, 0); o.stability.assign(n, 0);
    const auto st = n4m_cluster_hdbscan(
        ctx, &X, mcs, ms, method, single, o.labels.data(), o.membership.data(), o.outlier.data(),
        &o.n_clusters, o.persistence.data(), &o.n_nodes, o.tree_parent.data(), o.tree_size.data(),
        o.tree_label.data(), o.birth.data(), o.death.data(), o.stability.data());
    if (st == N4M_OK) {
        const auto k = static_cast<size_t>(o.n_nodes);
        for (auto* v : {&o.tree_parent, &o.tree_size, &o.tree_label}) v->resize(k);
        for (auto* v : {&o.birth, &o.death, &o.stability}) v->resize(k);
        o.persistence.resize(static_cast<size_t>(o.n_clusters));
    }
    return st;
}

bool close(double got, double want) {
    if (std::isnan(want)) return std::isnan(got);
    if (std::isinf(want)) return got == want;
    return std::abs(got - want) <= 1e-12 * std::max(1.0, std::abs(want));
}

std::vector<int64_t> int_array(const std::string& s, const std::string& key, size_t lo, size_t hi) {
    size_t pos = find_value_for_key(s, key, lo, hi);
    REQUIRE(s[pos] == '[');
    std::vector<int64_t> out;
    ++pos;
    while (true) {
        skip_ws(s, pos);
        if (s[pos] == ']') break;
        char* tail = nullptr;
        out.push_back(std::strtoll(s.c_str() + pos, &tail, 10));
        pos = static_cast<size_t>(tail - s.c_str());
        skip_ws(s, pos);
        if (s[pos] == ',') ++pos;
    }
    return out;
}

std::vector<double> hex_array(const std::string& s, const std::string& key, size_t lo, size_t hi) {
    size_t pos = find_value_for_key(s, key, lo, hi);
    std::vector<double> out;
    parse_hex_double_array(s, pos, out);
    return out;
}

// Bijection from produced labels to reference labels with identical noise.
std::map<int64_t, int64_t> match_partition(const std::vector<int64_t>& got,
                                           const std::vector<int64_t>& want) {
    REQUIRE(got.size() == want.size());
    std::map<int64_t, int64_t> forward, backward;
    for (size_t i = 0; i < got.size(); ++i) {
        REQUIRE((got[i] < 0) == (want[i] < 0));
        if (got[i] < 0) continue;
        const auto f = forward.emplace(got[i], want[i]).first;
        const auto b = backward.emplace(want[i], got[i]).first;
        REQUIRE(f->second == want[i] && b->second == got[i]);
    }
    return forward;
}

void gate_case(n4m_context_t* ctx, const std::string& s, size_t lo, size_t hi) {
    size_t name_pos = find_value_for_key(s, "name", lo, hi);
    const std::string name = parse_string(s, name_pos);
    const auto rows = parse_int64(s, find_value_for_key(s, "rows", lo, hi));
    const auto cols = parse_int64(s, find_value_for_key(s, "cols", lo, hi));
    auto [pb, pe] = read_value_span(s, find_value_for_key(s, "params", lo, hi));
    const std::string params = s.substr(pb, pe - pb);
    const auto mcs = params_get_int(params, "min_cluster_size", 0);
    const auto ms = params_get_int(params, "min_samples", 0);
    const auto method = static_cast<int32_t>(params_get_int(params, "selection_method", -1));
    const auto single = static_cast<int32_t>(params_get_int(params, "allow_single_cluster", -1));
    auto x = hex_array(s, "input_hex", lo, hi);
    REQUIRE(static_cast<int64_t>(x.size()) == rows * cols);
    n4m_matrix_view_t X{};
    REQUIRE(n4m_matrix_view_init_rowmajor(&X, x.data(), rows, cols, N4M_DTYPE_F64) == N4M_OK);
    Output o;
    REQUIRE(run(ctx, X, mcs, ms, method, single, o) == N4M_OK);

    const auto map = match_partition(o.labels, int_array(s, "labels", lo, hi));
    REQUIRE(o.n_clusters == parse_int64(s, find_value_for_key(s, "n_clusters", lo, hi)));
    REQUIRE(static_cast<int64_t>(map.size()) == o.n_clusters);
    const auto membership = hex_array(s, "membership_hex", lo, hi);
    const auto outlier = hex_array(s, "outlier_scores_hex", lo, hi);
    for (size_t i = 0; i < o.labels.size(); ++i)
        REQUIRE(close(o.membership[i], membership[i]) && close(o.outlier[i], outlier[i]));
    const auto persistence = hex_array(s, "persistence_hex", lo, hi);
    for (const auto& [got, want] : map)
        REQUIRE(close(o.persistence[static_cast<size_t>(got)], persistence[static_cast<size_t>(want)]));

    REQUIRE(o.tree_parent == int_array(s, "tree_parent", lo, hi));
    REQUIRE(o.tree_size == int_array(s, "tree_size", lo, hi));
    const auto tree_label = int_array(s, "tree_label", lo, hi);
    const auto birth = hex_array(s, "tree_lambda_birth_hex", lo, hi);
    const auto death = hex_array(s, "tree_lambda_death_hex", lo, hi);
    const auto stability = hex_array(s, "tree_stability_hex", lo, hi);
    for (size_t k = 0; k < tree_label.size(); ++k) {
        REQUIRE(o.tree_label[k] < 0 ? tree_label[k] < 0 : map.at(o.tree_label[k]) == tree_label[k]);
        REQUIRE(close(o.birth[k], birth[k]) && close(o.death[k], death[k]) &&
                close(o.stability[k], stability[k]));
    }

    // A column-major copy and a row-strided view give identical outputs.
    std::vector<double> colmajor(x.size()), padded(x.size() * 2);
    for (int64_t i = 0; i < rows; ++i) for (int64_t j = 0; j < cols; ++j) {
        colmajor[static_cast<size_t>(j * rows + i)] = x[static_cast<size_t>(i * cols + j)];
        padded[static_cast<size_t>(i * 2 * cols + j)] = x[static_cast<size_t>(i * cols + j)];
    }
    n4m_matrix_view_t C{}, P{};
    REQUIRE(n4m_matrix_view_init_colmajor(&C, colmajor.data(), rows, cols, N4M_DTYPE_F64) == N4M_OK);
    REQUIRE(n4m_matrix_view_init_strided(&P, padded.data(), rows, cols, 2 * cols, 1, N4M_DTYPE_F64) == N4M_OK);
    for (const auto* view : {&C, &P}) {
        Output again;
        REQUIRE(run(ctx, *view, mcs, ms, method, single, again) == N4M_OK);
        REQUIRE(again.labels == o.labels && again.membership == o.membership &&
                again.tree_parent == o.tree_parent);
    }
    std::printf("hdbscan gate %-40s clusters=%lld ok\n", name.c_str(),
                static_cast<long long>(o.n_clusters));
}

double ari(n4m_context_t* ctx, const std::vector<int64_t>& a, const std::vector<int64_t>& b) {
    double out = 0.0;
    REQUIRE(n4m_preflight_adjusted_rand_index(ctx, a.data(), b.data(),
                                              static_cast<int64_t>(a.size()), &out) == N4M_OK);
    return out;
}
}  // namespace

int main() {
    n4m_context_t* ctx = nullptr;
    try {
        REQUIRE(n4m_context_create(&ctx) == N4M_OK);
        const std::string s = slurp(std::string(N4M_PARITY_FIXTURE_DIR) + "/hdbscan_v1.json");
        REQUIRE(s.find("\"n4m_hdbscan_v1\"") != std::string::npos);
        const auto [lo, hi] = find_cases_array(s);
        const auto spans = list_case_object_spans(s, lo, hi);
        REQUIRE(spans.size() == 8);
        for (const auto& [a, b] : spans) gate_case(ctx, s, a, b);

        // Argument validation.
        double x[8] = {0, 0, 1, 1, 5, 5, 6, 6};
        n4m_matrix_view_t X{};
        REQUIRE(n4m_matrix_view_init_rowmajor(&X, x, 4, 2, N4M_DTYPE_F64) == N4M_OK);
        Output o;
        REQUIRE(run(ctx, X, 1, 2, 0, 0, o) == N4M_ERR_INVALID_ARGUMENT);
        REQUIRE(run(ctx, X, 2, 0, 0, 0, o) == N4M_ERR_INVALID_ARGUMENT);
        REQUIRE(run(ctx, X, 2, 5, 0, 0, o) == N4M_ERR_INVALID_ARGUMENT);
        REQUIRE(run(ctx, X, 2, 2, 2, 0, o) == N4M_ERR_INVALID_ARGUMENT);
        REQUIRE(run(ctx, X, 2, 2, 0, 3, o) == N4M_ERR_INVALID_ARGUMENT);
        REQUIRE(run(ctx, X, 2, 2, 0, 0, o) == N4M_OK);
        REQUIRE(o.n_clusters == 2 && o.labels[0] == o.labels[1] && o.labels[2] == o.labels[3] &&
                o.labels[0] != o.labels[2]);
        x[3] = std::nan("");
        REQUIRE(run(ctx, X, 2, 2, 0, 0, o) == N4M_ERR_INVALID_ARGUMENT);
        std::vector<double> big(60000, 0.0);
        n4m_matrix_view_t B{};
        REQUIRE(n4m_matrix_view_init_rowmajor(&B, big.data(), 60000, 1, N4M_DTYPE_F64) == N4M_OK);
        REQUIRE(run(ctx, B, 2, 2, 0, 0, o) == N4M_ERR_UNSUPPORTED);
        int64_t labels[4];
        REQUIRE(n4m_cluster_hdbscan(ctx, &X, 2, 2, 0, 0, labels, nullptr, nullptr, nullptr,
                                      nullptr, nullptr, nullptr, nullptr, nullptr, nullptr,
                                      nullptr, nullptr) == N4M_ERR_NULL_POINTER);

        // Regression (review 2026-10-13): squared distances of [0, 1e155,
        // 2e155, 3e155] overflowed to inf, Prim emitted self-edges and the
        // condensed tree had 7 nodes for 4 rows, written past the caller's
        // 4-element buffers. The rule-13 domain (nonzero |x| in
        // [2^-256, 2^256], max/min nonzero |x| <= 2^32, rule 15) refuses such
        // inputs before computing; sentinels check that nothing is written.
        {
            const double sentinel = -12345.0;
            auto guarded = [&](std::vector<double> data, n4m_status_t expect, Output& out) {
                const auto rows = static_cast<int64_t>(data.size());
                n4m_matrix_view_t V{};
                REQUIRE(n4m_matrix_view_init_rowmajor(&V, data.data(), rows, 1, N4M_DTYPE_F64) == N4M_OK);
                const auto cap = static_cast<size_t>(rows), pad = size_t{8};
                std::vector<int64_t> lab(cap + pad, -777), par(cap + pad, -777), siz(cap + pad, -777),
                    tl(cap + pad, -777);
                std::vector<double> mem(cap + pad, sentinel), out_s(cap + pad, sentinel),
                    pers(cap + pad, sentinel), bir(cap + pad, sentinel), dea(cap + pad, sentinel),
                    sta(cap + pad, sentinel);
                int64_t nc = -1, nn = -1;
                REQUIRE(n4m_cluster_hdbscan(ctx, &V, 2, 2, 0, 0, lab.data(), mem.data(), out_s.data(),
                                            &nc, pers.data(), &nn, par.data(), siz.data(), tl.data(),
                                            bir.data(), dea.data(), sta.data()) == expect);
                const size_t first_guard = expect == N4M_OK ? cap : 0;
                for (size_t i = first_guard; i < cap + pad; ++i)
                    REQUIRE(lab[i] == -777 && par[i] == -777 && siz[i] == -777 && tl[i] == -777 &&
                            mem[i] == sentinel && out_s[i] == sentinel && pers[i] == sentinel &&
                            bir[i] == sentinel && dea[i] == sentinel && sta[i] == sentinel);
                if (expect != N4M_OK) return;
                REQUIRE(nn >= 1 && nn <= rows && nc >= 0 && nc <= rows);
                out.labels.assign(lab.begin(), lab.begin() + rows);
                out.membership.assign(mem.begin(), mem.begin() + rows);
                out.tree_parent.assign(par.begin(), par.begin() + nn);
                out.birth.assign(bir.begin(), bir.begin() + nn);
                out.n_clusters = nc;
            };
            const double up = std::ldexp(1.0, 254), down = std::ldexp(1.0, -256);
            Output u, h, t, ignored;
            guarded({0, 1, 2, 3}, N4M_OK, u);
            guarded({0, up, 2 * up, 3 * up}, N4M_OK, h);       // largest 3 * 2^254 <= 2^256
            guarded({0, down, 2 * down, 3 * down}, N4M_OK, t);  // smallest exactly 2^-256
            // Power-of-two rescaling keeps partition and memberships exactly.
            for (const Output* rescaled : {&h, &t}) {
                REQUIRE(rescaled->labels == u.labels && rescaled->tree_parent == u.tree_parent &&
                        rescaled->n_clusters == u.n_clusters && rescaled->membership == u.membership);
            }
            for (size_t k = 0; k < u.birth.size(); ++k) {
                REQUIRE(h.birth[k] == std::ldexp(u.birth[k], -254));
                REQUIRE(t.birth[k] == std::ldexp(u.birth[k], 256));
            }
            // Just outside the domain on each side, and the review input.
            guarded({0, 4 * up, 5 * up, 6 * up}, N4M_ERR_UNSUPPORTED, ignored);    // above 2^256
            guarded({0, down / 2, down, 2 * down}, N4M_ERR_UNSUPPORTED, ignored);  // below 2^-256
            guarded({1, 2, std::ldexp(1.0, N4M_DOMAIN_MAX_SPREAD_LOG2)}, N4M_OK, ignored);  // spread 2^32
            guarded({1, 2, std::ldexp(1.0, N4M_DOMAIN_MAX_SPREAD_LOG2) * (1 + 0x1p-52)},
                    N4M_ERR_UNSUPPORTED, ignored);
            guarded({0, 1, 2, std::ldexp(1.0, 40)}, N4M_ERR_UNSUPPORTED, ignored);  // spread 2^40
            guarded({0, 1e155, 2e155, 3e155}, N4M_ERR_UNSUPPORTED, ignored);
            guarded({-1e308, 1e308}, N4M_ERR_UNSUPPORTED, ignored);
        }

        // ARI reference values from scikit-learn 1.9.1 adjusted_rand_score.
        REQUIRE(close(ari(ctx, {0, 0, 1, 2}, {0, 0, 1, 1}), 0.5714285714285714));
        REQUIRE(close(ari(ctx, {0, 0, 1, 1}, {0, 1, 0, 1}), -0.5));
        REQUIRE(close(ari(ctx, {0, 0, 1, 1, 2, 2}, {5, 5, 7, 7, 9, 9}), 1.0));
        REQUIRE(close(ari(ctx, {0, 0, 0, 1, 1, 1}, {0, 0, 1, 1, 2, 2}), 0.24242424242424243));
        REQUIRE(std::isnan(ari(ctx, {3, 3, 3}, {1, 1, 1})));
        REQUIRE(std::isnan(ari(ctx, {0, 1, 2}, {2, 0, 1})));
        REQUIRE(std::isnan(ari(ctx, {7}, {7})));
        double out = 0.0;
        REQUIRE(n4m_preflight_adjusted_rand_index(ctx, labels, labels, -1, &out) ==
                N4M_ERR_INVALID_ARGUMENT);
        n4m_context_destroy(ctx);
        std::puts("n4m_hdbscan_tests: ok");
        return 0;
    } catch (const std::exception& e) {
        std::fprintf(stderr, "n4m_hdbscan_tests failed: %s\n", e.what());
        if (ctx) n4m_context_destroy(ctx);
        return 1;
    }
}
